/**
 * 表示不同纹理图标的枚举，
 * 这些图标可用于定位条上的路径点显示。
 */
export enum WaypointTexture {
    /**
     * @remarks
     * 圆形路径点图标纹理。
     *
     */
    Circle = 'minecraft:circle',
    /**
     * @remarks
     * 小方形路径点图标纹理。
     *
     */
    SmallSquare = 'minecraft:small_square',
    /**
     * @remarks
     * 小星形路径点图标纹理。
     *
     */
    SmallStar = 'minecraft:small_star',
    /**
     * @remarks
     * 方形路径点图标纹理。
     *
     */
    Square = 'minecraft:square',
}